# Expected values are SymPy's outputs for the same calls (manualintegrate).

skip_on_cran()

x <- Symbol("x"); y <- Symbol("y"); z <- Symbol("z"); u <- Symbol("u"); n <- Symbol("n"); a <- Symbol("a"); b <- Symbol("b"); c <- Symbol("c"); d <- Symbol("d"); e <- Symbol("e")
mi_fmt <- function(v) if (is.null(v)) "None" else gsub("\n", " ", sstr(v))

test_that("manualintegrate match SymPy", {
  expect_equal(mi_fmt(manualintegrate(sqrt(a * x + b) / x, x)), "Piecewise((sqrt(b)*log(x), Eq(a, 0)), (-2*b/sqrt(a*x + b) + 2*sqrt(a*x + b), Eq(b, 0)), (2*b*atan(sqrt(a*x + b)/sqrt(-b))/sqrt(-b) + 2*sqrt(a*x + b), True))")
  expect_equal(mi_fmt(manualintegrate(exp(10 * x) * sin(exp(x)), x)), "-exp(9*x)*cos(exp(x)) + 9*exp(8*x)*sin(exp(x)) + 72*exp(7*x)*cos(exp(x)) - 504*exp(6*x)*sin(exp(x)) - 3024*exp(5*x)*cos(exp(x)) + 15120*exp(4*x)*sin(exp(x)) + 60480*exp(3*x)*cos(exp(x)) - 181440*exp(2*x)*sin(exp(x)) - 362880*exp(x)*cos(exp(x)) + 362880*sin(exp(x))")
  expect_equal(mi_fmt(manualintegrate(y, x)), "x*y")
  expect_equal(mi_fmt(manualintegrate(exp(as_sym(2)), x)), "x*exp(2)")
  expect_equal(mi_fmt(manualintegrate(x ^ 2, x)), "x^3/3")
  expect_equal(mi_fmt(manualintegrate(3 * x ^ 2 + 4 * x ^ 3, x)), "x^4 + x^3")
  expect_equal(mi_fmt(manualintegrate((x + 2) ^ 3, x)), "(x + 2)^4/4")
  expect_equal(mi_fmt(manualintegrate((3 * x + 4) ^ 2, x)), "(3*x + 4)^3/9")
  expect_equal(mi_fmt(manualintegrate((u + 2) ^ 3, u)), "(u + 2)^4/4")
  expect_equal(mi_fmt(manualintegrate((3 * u + 4) ^ 2, u)), "(3*u + 4)^3/9")
  expect_equal(mi_fmt(manualintegrate(exp(2 * x), x)), "exp(2*x)/2")
  expect_equal(mi_fmt(manualintegrate(2 ^ x, x)), "2^x/log(2)")
  expect_equal(mi_fmt(manualintegrate(1 / x, x)), "log(x)")
  expect_equal(mi_fmt(manualintegrate(1 / (2 * x + 3), x)), "log(2*x + 3)/2")
  expect_equal(mi_fmt(manualintegrate(log(x) ^ 2 / x, x)), "log(x)^3/3")
  expect_equal(mi_fmt(manualintegrate(exp(x) * sin(x), x)), "exp(x)*sin(x)/2 - exp(x)*cos(x)/2")
  expect_equal(mi_fmt(manualintegrate(2 * x * cos(x), x)), "2*x*sin(x) + 2*cos(x)")
  expect_equal(mi_fmt(manualintegrate(x * log(x), x)), "x^2*log(x)/2 - x^2/4")
  expect_equal(mi_fmt(manualintegrate(log(x), x)), "x*log(x) - x")
  expect_equal(mi_fmt(manualintegrate((3 * x ^ 2 + 5) * exp(x), x)), "3*x^2*exp(x) - 6*x*exp(x) + 11*exp(x)")
  expect_equal(mi_fmt(manualintegrate(atan(x), x)), "x*atan(x) - log(x^2 + 1)/2")
  expect_equal(mi_fmt(manualintegrate(sin(x), x)), "-cos(x)")
  expect_equal(mi_fmt(manualintegrate(tan(x), x)), "-log(cos(x))")
  expect_equal(mi_fmt(manualintegrate(sec(x), x)), "log(tan(x) + sec(x))")
  expect_equal(mi_fmt(manualintegrate(csc(x), x)), "-log(cot(x) + csc(x))")
  expect_equal(mi_fmt(manualintegrate(sin(x) * cos(x), x)), "-cos(x)^2/2")
  expect_equal(mi_fmt(manualintegrate(-sec(x) * tan(x), x)), "-sec(x)")
  expect_equal(mi_fmt(manualintegrate(csc(x) * cot(x), x)), "-csc(x)")
  expect_equal(mi_fmt(manualintegrate(sec(x) ^ 2, x)), "tan(x)")
  expect_equal(mi_fmt(manualintegrate(csc(x) ^ 2, x)), "-cot(x)")
  expect_equal(mi_fmt(manualintegrate(x * sec(x ^ 2), x)), "log(tan(x^2) + sec(x^2))/2")
  expect_equal(mi_fmt(manualintegrate(cos(x) * csc(sin(x)), x)), "-log(cot(sin(x)) + csc(sin(x)))")
  expect_equal(mi_fmt(manualintegrate(cos(3 * x) * sec(x), x)), "-x + sin(2*x)")
  expect_equal(mi_fmt(manualintegrate(sin(3 * x) * sec(x), x)), "log(-2*cos(2*x) - 2)/2 - cos(2*x)")
  expect_equal(mi_fmt(manualintegrate(sin(x) ^ 2 * cos(x), x)), "sin(x)^3/3")
  expect_equal(mi_fmt(manualintegrate(sin(x) ^ 2 * cos(x) ^ 2, x)), "x/8 - sin(4*x)/32")
  expect_equal(mi_fmt(manualintegrate(sin(x) * cos(x) ^ 3, x)), "-cos(x)^4/4")
  expect_equal(mi_fmt(manualintegrate(sin(x) ^ 3 * cos(x) ^ 2, x)), "cos(x)^5/5 - cos(x)^3/3")
  expect_equal(mi_fmt(manualintegrate(tan(x) ^ 3 * sec(x), x)), "sec(x)^3/3 - sec(x)")
  expect_equal(mi_fmt(manualintegrate(tan(x) * sec(x) ^ 2, x)), "sec(x)^2/2")
  expect_equal(mi_fmt(manualintegrate(cot(x) ^ 5 * csc(x), x)), "-csc(x)^5/5 + 2*csc(x)^3/3 - csc(x)")
  expect_equal(mi_fmt(manualintegrate(cot(x) ^ 2 * csc(x) ^ 6, x)), "-cot(x)^7/7 - 2*cot(x)^5/5 - cot(x)^3/3")
  expect_equal(mi_fmt(manualintegrate(exp(x) / (1 + exp(2 * x)), x)), "atan(exp(x))")
  expect_equal(mi_fmt(manualintegrate(1 / (4 + 9 * x ^ 2), x)), "atan(3*x/2)/6")
  expect_equal(mi_fmt(manualintegrate(1 / (16 + 16 * x ^ 2), x)), "atan(x)/16")
  expect_equal(mi_fmt(manualintegrate(1 / (4 + x ^ 2), x)), "atan(x/2)/2")
  expect_equal(mi_fmt(manualintegrate(1 / (1 + 4 * x ^ 2), x)), "atan(2*x)/2")
  expect_equal(mi_fmt(manualintegrate(1 / (4 + 4 * x ^ 2), x)), "atan(x)/4")
  expect_equal(mi_fmt(manualintegrate(1 / (a + b * x ^ 2), x)), "Piecewise((x/a, Eq(b, 0)), (-1/(b*x), Eq(a, 0)), (atan(x/sqrt(a/b))/(b*sqrt(a/b)), True))")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(1 - x ^ 2), x)), "asin(x)")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(4 - 4 * x ^ 2), x)), "asin(x)/2")
  expect_equal(mi_fmt(manualintegrate(3 / sqrt(1 - 9 * x ^ 2), x)), "asin(3*x)")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(4 - 9 * x ^ 2), x)), "asin(3*x/2)/3")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(x ^ 2 + 1), x)), "asinh(x)")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(x ^ 2 + 4), x)), "asinh(x/2)")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(4 * x ^ 2 + 4), x)), "asinh(x)/2")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(4 * x ^ 2 + 1), x)), "asinh(2*x)/2")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(x ^ 2 - 1), x)), "log(2*x + 2*sqrt(x^2 - 1))")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(x ^ 2 - 4), x)), "log(2*x + 2*sqrt(x^2 - 4))")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(4 * x ^ 2 - 4), x)), "log(8*x + 4*sqrt(4*x^2 - 4))/2")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(9 * x ^ 2 - 1), x)), "log(18*x + 6*sqrt(9*x^2 - 1))/3")
  expect_equal(mi_fmt(manualintegrate(asin(x), x)), "x*asin(x) + sqrt(1 - x^2)")
  expect_equal(mi_fmt(manualintegrate(asin(a * x), x)), "Piecewise(((a*x*asin(a*x) + sqrt(-a^2*x^2 + 1))/a, Ne(a, 0)), (0, True))")
  expect_equal(mi_fmt(manualintegrate(x * asin(a * x), x)), "-a*Piecewise((-x*sqrt(-a^2*x^2 + 1)/(2*a^2) + log(-2*a^2*x + 2*sqrt(-a^2)*sqrt(-a^2*x^2 + 1))/(2*a^2*sqrt(-a^2)), Ne(a^2, 0)), (x^3/3, True))/2 + x^2*asin(a*x)/2")
  expect_equal(mi_fmt(manualintegrate(acos(x), x)), "x*acos(x) - sqrt(1 - x^2)")
  expect_equal(mi_fmt(manualintegrate(acos(a * x), x)), "Piecewise(((a*x*acos(a*x) - sqrt(-a^2*x^2 + 1))/a, Ne(a, 0)), (pi*x/2, True))")
  expect_equal(mi_fmt(manualintegrate(x * acos(a * x), x)), "a*Piecewise((-x*sqrt(-a^2*x^2 + 1)/(2*a^2) + log(-2*a^2*x + 2*sqrt(-a^2)*sqrt(-a^2*x^2 + 1))/(2*a^2*sqrt(-a^2)), Ne(a^2, 0)), (x^3/3, True))/2 + x^2*acos(a*x)/2")
  expect_equal(mi_fmt(manualintegrate(atan(a * x), x)), "Piecewise(((a*x*atan(a*x) - log(a^2*x^2 + 1)/2)/a, Ne(a, 0)), (0, True))")
  expect_equal(mi_fmt(manualintegrate(x * atan(a * x), x)), "-a*(x/a^2 - Piecewise((x, Eq(a^2, 0)), (atan(x/sqrt(a^(-2)))/(a^2*sqrt(a^(-2))), True))/a^2)/2 + x^2*atan(a*x)/2")
  expect_equal(mi_fmt(manualintegrate(acsc(x), x)), "x*acsc(x) - log(sqrt(1 - 1/x^2) - 1)/2 + log(sqrt(1 - 1/x^2) + 1)/2")
  expect_equal(mi_fmt(manualintegrate(acsc(a * x), x)), "(a*x*acsc(a*x) - log(sqrt(1 - 1/(a^2*x^2)) - 1)/2 + log(sqrt(1 - 1/(a^2*x^2)) + 1)/2)/a")
  expect_equal(mi_fmt(manualintegrate(x * acsc(a * x), x)), "x^2*acsc(a*x)/2 + x*sqrt(1 - 1/(a^2*x^2))/(2*a)")
  expect_equal(mi_fmt(manualintegrate(asec(x), x)), "x*asec(x) + log(sqrt(1 - 1/x^2) - 1)/2 - log(sqrt(1 - 1/x^2) + 1)/2")
  expect_equal(mi_fmt(manualintegrate(asec(a * x), x)), "(a*x*asec(a*x) + log(sqrt(1 - 1/(a^2*x^2)) - 1)/2 - log(sqrt(1 - 1/(a^2*x^2)) + 1)/2)/a")
  expect_equal(mi_fmt(manualintegrate(x * asec(a * x), x)), "x^2*asec(a*x)/2 - x*sqrt(1 - 1/(a^2*x^2))/(2*a)")
  expect_equal(mi_fmt(manualintegrate(acot(x), x)), "x*acot(x) + log(x^2 + 1)/2")
  expect_equal(mi_fmt(manualintegrate(acot(a * x), x)), "Piecewise(((a*x*acot(a*x) + log(a^2*x^2 + 1)/2)/a, Ne(a, 0)), (pi*x/2, True))")
  expect_equal(mi_fmt(manualintegrate(x * acot(a * x), x)), "a*(x/a^2 - Piecewise((x, Eq(a^2, 0)), (atan(x/sqrt(a^(-2)))/(a^2*sqrt(a^(-2))), True))/a^2)/2 + x^2*acot(a*x)/2")
  expect_equal(mi_fmt(manualintegrate((exp(x) - exp(-x)) / x, x)), "-Ei(-x) + Ei(x)")
  expect_equal(mi_fmt(manualintegrate(1 / (4 - x ^ 2), x)), "-log(x - 2)/4 + log(x + 2)/4")
  expect_equal(mi_fmt(manualintegrate(1 / (-1 + x ^ 2), x)), "log(x - 1)/2 - log(x + 1)/2")
  expect_equal(mi_fmt(manualintegrate(S_Pi * Derivative(x ^ 2 + 2 * x + 3), x)), "pi*(x^2 + 2*x + 3)")
  expect_equal(mi_fmt(manualintegrate(Derivative(x ^ 2 + 2 * x + 3, y), x)), "Integral(Derivative(x^2 + 2*x + 3, y), x)")
  expect_equal(mi_fmt(manualintegrate(Derivative(sin(x), x, x, x, y), x)), "Derivative(sin(x), (x, 2), y)")
  expect_equal(mi_fmt(manualintegrate(DiracDelta(a + b * x, 1), x)), "Piecewise((DiracDelta(a + b*x)/b, Ne(b, 0)), (x*DiracDelta(a, 1), True))")
  expect_equal(mi_fmt(manualintegrate(Heaviside(x), x)), "x*Heaviside(x)")
  expect_equal(mi_fmt(manualintegrate(x * Heaviside(2), x)), "x^2/2")
  expect_equal(mi_fmt(manualintegrate(x * Heaviside(-2), x)), "0")
  expect_equal(mi_fmt(manualintegrate(x * Heaviside(x), x)), "x^2*Heaviside(x)/2")
  expect_equal(mi_fmt(manualintegrate(x * Heaviside(-x), x)), "x^2*Heaviside(-x)/2")
  expect_equal(mi_fmt(manualintegrate(Heaviside(2 * x + 4), x)), "(x + 2)*Heaviside(2*x + 4)")
  expect_equal(mi_fmt(manualintegrate(Heaviside(x + 1) * Heaviside(1 - x) * x ^ 2, x)), "((x^3/3 + 1/3)*Heaviside(x + 1) - 2/3)*Heaviside(1 - x)")
  expect_equal(mi_fmt(manualintegrate(sin(7 + x) * Heaviside(3 * x - 7), x)), "(-cos(x + 7) + cos(28/3))*Heaviside(3*x - 7)")
  expect_equal(mi_fmt(manualintegrate(sin(y + x) * Heaviside(3 * x - y), x)), "(cos(4*y/3) - cos(x + y))*Heaviside(3*x - y)")
  expect_equal(mi_fmt(manualintegrate(x ^ y, x)), "Piecewise((x^(y + 1)/(y + 1), Ne(y, -1)), (log(x), True))")
  expect_equal(mi_fmt(manualintegrate(diff(exp(x + x ^ 2)), x)), "exp(x^2 + x)")
  expect_equal(mi_fmt(manualintegrate(y ^ x, x)), "Piecewise((y^x/log(y), Ne(log(y), 0)), (x, True))")
  expect_equal(mi_fmt(manualintegrate(y ^ (n * x), x)), "Piecewise((x, Eq(n, 0)), (y^(n*x)/(n*log(y)), Ne(log(y), 0)), (x, True))")
  expect_equal(mi_fmt(manualintegrate(exp(n * x), x)), "Piecewise((exp(n*x)/n, Ne(n, 0)), (x, True))")
  expect_equal(mi_fmt(manualintegrate((y + 1) ^ x, x)), "Piecewise(((y + 1)^x/log(y + 1), Ne(log(y + 1), 0)), (x, True))")
  expect_equal(mi_fmt(manualintegrate((y + 1) ^ (n * x), x)), "Piecewise((x, Eq(n, 0)), ((y + 1)^(n*x)/(n*log(y + 1)), Ne(log(y + 1), 0)), (x, True))")
  expect_equal(mi_fmt(manualintegrate(1 / ((x ^ a + y ^ b + 4) * sqrt(a * x ^ 2 + 1)), x)), "Integral(1/(sqrt(a*x^2 + 1)*(x^a + y^b + 4)), x)")
  expect_equal(mi_fmt(manualintegrate(1 / ((x ^ 2 + 4) * sqrt(4 * x ^ 2 + 1)), x)), "-sqrt(15)*(log(-8*sqrt(15) + 31 + (2*x + sqrt(4*x^2 + 1))^(-2)) - log(8*sqrt(15) + 31 + (2*x + sqrt(4*x^2 + 1))^(-2)))/60")
  expect_equal(mi_fmt(manualintegrate(1 / (x - a ^ x + x * b ^ 2), x)), "Integral(1/(-a^x + b^2*x + x), x)")
  expect_equal(mi_fmt(manualintegrate(asin(x) * log(x), x)), "-x*asin(x) - 2*sqrt(1 - x^2) + (x*asin(x) + sqrt(1 - x^2))*log(x) - log(sqrt(1 - x^2) - 1)/2 + log(sqrt(1 - x^2) + 1)/2")
  expect_equal(mi_fmt(manualintegrate(acos(x) * log(x), x)), "-x*acos(x) + 2*sqrt(1 - x^2) + (x*acos(x) - sqrt(1 - x^2))*log(x) + log(sqrt(1 - x^2) - 1)/2 - log(sqrt(1 - x^2) + 1)/2")
  expect_equal(mi_fmt(manualintegrate(atan(x) * log(x), x)), "-x*atan(x) + (x*atan(x) - log(x^2 + 1)/2)*log(x) + log(x^2 + 1)/2 + Integral(log(x^2 + 1)/x, x)/2")
  expect_equal(mi_fmt(manualintegrate(sin(2 * x) * exp(x), x)), "exp(x)*sin(2*x)/5 - 2*exp(x)*cos(2*x)/5")
  expect_equal(mi_fmt(manualintegrate((x - 3) / (x ^ 2 - 2 * x + 2) ^ 2, x)), "(4 - 4*x)/(4*x^2 - 8*x + 8) - atan(x - 1) - 1/(2*(x^2 - 2*x + 2))")
  expect_equal(mi_fmt(manualintegrate((4 * x ^ 4 + 4 * x ^ 3 + 16 * x ^ 2 + 12 * x + 8) / (x ^ 6 + 2 * x ^ 5 + 3 * x ^ 4 + 4 * x ^ 3 + 3 * x ^ 2 + 2 * x + 1), x)), "8*x/(4*x^2 + 4) + 3*atan(x) - 1/(x^2 + 1) - 3/(x + 1)")
  expect_equal(mi_fmt(manualintegrate(x ^ 2 / (x ^ 2 - c), x)), "c*Piecewise((-1/x, Eq(c, 0)), (atan(x/sqrt(-c))/sqrt(-c), True)) + x")
  expect_equal(mi_fmt(manualintegrate(sqrt(x - y) * log(z / x), x)), "4*y^2*Piecewise((-1/sqrt(x - y), Eq(y, 0)), (atan(sqrt(x - y)/sqrt(y))/sqrt(y), True))/3 - 4*y*sqrt(x - y)/3 + 2*(x - y)^(3/2)*log(z/x)/3 + 4*(x - y)^(3/2)/9")
  expect_equal(mi_fmt(manualintegrate(sqrt(x) * log(x), x)), "2*x^(3/2)*log(x)/3 - 4*x^(3/2)/9")
  expect_equal(mi_fmt(manualintegrate(sqrt(2 * x + 3) / (x + 1), x)), "2*sqrt(2*x + 3) + log(sqrt(2*x + 3) - 1) - log(sqrt(2*x + 3) + 1)")
  expect_equal(mi_fmt(manualintegrate(sqrt(2 * x + 3) / 2 * x, x)), "(2*x + 3)^(5/2)/20 - (2*x + 3)^(3/2)/4")
  expect_equal(mi_fmt(manualintegrate(x ^ Rational(3, 2) * log(x), x)), "2*x^(5/2)*log(x)/5 - 4*x^(5/2)/25")
  expect_equal(mi_fmt(manualintegrate(x ^ (-3) * log(x), x)), "-log(x)/(2*x^2) - 1/(4*x^2)")
  expect_equal(mi_fmt(manualintegrate(log(y) / (y ^ 2 * (1 - 1 / y)), y)), "(-log(y) + log(y - 1))*log(y) + log(y)^2/2 - Integral(log(y - 1)/y, y)")
  expect_equal(mi_fmt(manualintegrate(sin(2 * x), x)), "-cos(2*x)/2")
  expect_equal(mi_fmt(manualintegrate(cos(x) * sin(2 * x), x)), "-cos(x)/2 - cos(3*x)/6")
  expect_equal(mi_fmt(manualintegrate(sin(2 * x) * cos(x) / (1 + cos(x)), x)), "-2*log(cos(x) + 1) - cos(x)^2 + 2*cos(x)")
  expect_equal(mi_fmt(manualintegrate(sin(x) * cos(x) ^ 5, x)), "-cos(x)^6/6")
  expect_equal(mi_fmt(manualintegrate(exp(x) * cos(exp(x)), x)), "sin(exp(x))")
  expect_equal(mi_fmt(manualintegrate(exp(2 * x) * cos(exp(x)), x)), "exp(x)*sin(exp(x)) + cos(exp(x))")
  expect_equal(mi_fmt(manualintegrate(x / (x ^ 4 + 1), x)), "atan(x^2)/2")
  expect_equal(mi_fmt(manualintegrate(x ^ 2 / (x ^ 6 + 25), x)), "atan(x^3/5)/15")
  expect_equal(mi_fmt(manualintegrate(sin(x), y)), "y*sin(x)")
  expect_equal(mi_fmt(manualintegrate(exp(a * x ^ 2 + b), x)), "Piecewise((sqrt(pi)*exp(b)*erfi(sqrt(a)*x)/(2*sqrt(a)), Ne(a, 0)), (x*exp(b), True))")
  expect_equal(mi_fmt(manualintegrate(sin(a * x ^ 2 + b), x)), "Piecewise((sqrt(2)*sqrt(pi)*(sin(b)*fresnelc(sqrt(2)*sqrt(a)*x/sqrt(pi)) + cos(b)*fresnels(sqrt(2)*sqrt(a)*x/sqrt(pi)))/(2*sqrt(a)), Ne(a, 0)), (x*sin(b), True))")
  expect_equal(mi_fmt(manualintegrate(cos(a * x ^ 2 + b), x)), "Piecewise((sqrt(2)*sqrt(pi)*(-sin(b)*fresnels(sqrt(2)*sqrt(a)*x/sqrt(pi)) + cos(b)*fresnelc(sqrt(2)*sqrt(a)*x/sqrt(pi)))/(2*sqrt(a)), Ne(a, 0)), (x*cos(b), True))")
  expect_equal(mi_fmt(manualintegrate(x / sqrt(a + b * x) ^ 3, x)), "Piecewise((-2*(-a/sqrt(a + b*x) - sqrt(a + b*x))/b^2, Ne(b, 0)), (x^2/(2*a^(3/2)), True))")
  expect_equal(mi_fmt(manualintegrate(1 / sqrt(a + b * x + c * x ^ 2), x)), "Piecewise((log(b + 2*sqrt(c)*sqrt(a + b*x + c*x^2) + 2*c*x)/sqrt(c), Ne(c, 0) & Ne(a - b^2/(4*c), 0)), ((b/(2*c) + x)*log(b/(2*c) + x)/sqrt(c*(b/(2*c) + x)^2), Ne(c, 0)), (x/sqrt(a), Eq(b, 0)), (2*sqrt(a + b*x)/b, True))")
  expect_equal(mi_fmt(manualintegrate((d + e * x) / sqrt(a + b * x + c * x ^ 2), x)), "Piecewise((e*sqrt(a + b*x + c*x^2)/c + (-b*e/(2*c) + d)*log(b + 2*sqrt(c)*sqrt(a + b*x + c*x^2) + 2*c*x)/sqrt(c), Ne(c, 0) & Ne(a - b^2/(4*c), 0)), ((b/(2*c) + x)*(-b*e/(2*c) + d)*log(b/(2*c) + x)/sqrt(c*(b/(2*c) + x)^2) + e*sqrt(a + b*x + c*x^2)/c, Ne(c, 0)), ((d*x + e*x^2/2)/sqrt(a), Eq(b, 0)), (2*(d*sqrt(a + b*x) - e*(a*sqrt(a + b*x) - (a + b*x)^(3/2)/3)/b)/b, True))")
  expect_equal(mi_fmt(manualintegrate((3 * x ^ 3 - x ^ 2 + 2 * x - 4) / sqrt(x ^ 2 - 3 * x + 2), x)), "sqrt(x^2 - 3*x + 2)*(x^2 + 13*x/4 + 101/8) + 135*log(2*x + 2*sqrt(x^2 - 3*x + 2) - 3)/16")
  expect_equal(mi_fmt(manualintegrate(sqrt(a + c * x ^ 2), x)), "Piecewise((a*log(2*sqrt(c)*sqrt(a + c*x^2) + 2*c*x)/(2*sqrt(c)) + x*sqrt(a + c*x^2)/2, Ne(a, 0) & Ne(c, 0)), (a*x*log(x)/(2*sqrt(c*x^2)) + x*sqrt(a + c*x^2)/2, Ne(c, 0)), (sqrt(a)*x, True))")
  expect_equal(mi_fmt(manualintegrate(sqrt(a + b * x + c * x ^ 2), x)), "Piecewise(((b/(4*c) + x/2)*sqrt(a + b*x + c*x^2) + (a/2 - b^2/(8*c))*log(b + 2*sqrt(c)*sqrt(a + b*x + c*x^2) + 2*c*x)/sqrt(c), Ne(c, 0) & Ne(a - b^2/(4*c), 0)), ((b/(4*c) + x/2)*sqrt(a + b*x + c*x^2) + (a/2 - b^2/(8*c))*(b/(2*c) + x)*log(b/(2*c) + x)/sqrt(c*(b/(2*c) + x)^2), Ne(c, 0)), (sqrt(a)*x, Eq(b, 0)), (2*(a + b*x)^(3/2)/(3*b), True))")
  expect_equal(mi_fmt(manualintegrate(x ^ 7 / (49 * x ^ 2 + 1) ^ (3 * S_Half), x)), "sqrt(49*x^2 + 1)*(x^4/12005 - 3*x^2/588245 + 11/28824005) + 1/(5764801*sqrt(49*x^2 + 1))")
})
